// === Code node "Leer respuesta de Claude" ===
const r = $input.item.json;
if (r.stop_reason === 'refusal') throw new Error('Claude rechazó el pedido: revisar el video a mano');
const bloque = (r.content || []).find(b => b.type === 'text');
if (!bloque) throw new Error('Claude no devolvió texto');
const d = JSON.parse(bloque.text);
const cfg = $('Config del video').item.json;
const datos = $('Datos del negocio').item.json;
const hashtags = [...new Set([...(datos.hashtags_base || []), ...(d.hashtags || [])])].join(' ');
const limpio = String(d.titulo || 'reel').replace(/[\\/:*?"<>|]/g, '').slice(0, 60).trim();
// Portada: el gancho partido en renglones de ~18 letras (máx. 3)
const palabras = String(d.gancho || d.titulo || datos.nombre).toUpperCase().split(/\s+/).filter(Boolean);
const renglones = [];
for (const p of palabras) {
  const ult = renglones[renglones.length - 1];
  if (ult !== undefined && (ult + ' ' + p).length <= 18) renglones[renglones.length - 1] = ult + ' ' + p;
  else renglones.push(p);
}
const b64 = t => Buffer.from(String(t || ''), 'utf8').toString('base64');
return { json: {
  portada_b64: b64(renglones.slice(0, 3).join('\n')),
  portada_pie_b64: b64([datos.instagram, datos.telefono_reservas ? 'Reservas ' + datos.telefono_reservas : ''].filter(Boolean).join('  ·  ')),
  hist1_b64: b64(datos.historia_linea_1 || (datos.telefono_reservas ? 'RESERVAS ' + datos.telefono_reservas : datos.nombre)),
  hist2_b64: b64(datos.historia_linea_2 || datos.horario || ''),
  titulo: d.titulo,
  gancho: d.gancho,
  caption: [String(d.caption || '').trim(), datos.pie_caption].filter(Boolean).join('\n\n'),
  hashtags,
  nombre_archivo: `${cfg.fecha} - ${limpio}`,
}};

